# Try: output only positions of 3s as the grid, with center as something
grid = [
    [0, 0, 0, 3, 1, 0, 3, 3, 3],
    [0, 3, 3, 0, 1, 0, 3, 3, 0],
    [3, 0, 3, 0, 1, 0, 3, 0, 3],
    [3, 3, 0, 0, 1, 0, 3, 3, 3]
]

# Mark 3 positions, others as background
# Option: 3→2, all others→0
output_skeleton = []
for row in grid:
    new_row = []
    for cell in row:
        if cell == 3:
            new_row.append(2)  # Mark 3s as 2
        else:
            new_row.append(0)  # Others as 0 (or 1 for center?)
    output_skeleton.append(new_row)

print("Skeleton with center 0:")
for row in output_skeleton:
    print(row)

# Try with center as 1:
output_skeleton_c = []
for row in grid:
    new_row = []
    for cell in row:
        if cell == 3:
            new_row.append(2)
        elif cell == 0:
            new_row.append(0)
        else:  # cell == 1
            new_row.append(1)
    output_skeleton_c.append(new_row)

print("\nSkeleton with center 1:")
for row in output_skeleton_c:
    print(row)

